use anyhow::{anyhow, Result};
use serde::{Deserialize, Serialize};

#[derive(Debug, Clone, Copy, Serialize, Deserialize, PartialEq, Eq, Default)]
#[serde(rename_all = "camelCase")]
pub enum Mode {
    #[default]
    Default,
    AcceptEdits,
    Auto,
    DontAsk,
    BypassPermissions,
    Plan,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Rule {
    pub tool: String,
    pub arg_pattern: Option<String>,
}

impl Rule {
    pub fn parse(s: &str) -> Result<Self> {
        let s = s.trim();
        if let Some((tool, rest)) = s.split_once('(') {
            let arg = rest
                .strip_suffix(')')
                .ok_or_else(|| anyhow!("rule missing closing paren: {s}"))?;
            Ok(Self {
                tool: tool.trim().to_string(),
                arg_pattern: Some(arg.trim().to_string()),
            })
        } else {
            Ok(Self {
                tool: s.to_string(),
                arg_pattern: None,
            })
        }
    }

    pub fn matches(&self, tool: &str, args: &serde_json::Value) -> bool {
        if !self.tool.eq_ignore_ascii_case(tool) && self.tool != "*" {
            return false;
        }
        let pat = match &self.arg_pattern {
            Some(p) => p,
            None => return true,
        };
        if pat == "*" {
            return true;
        }
        let s = match args {
            serde_json::Value::String(s) => s.clone(),
            _ => serde_json::to_string(args).unwrap_or_default(),
        };
        glob_match(pat, &s)
    }
}

#[derive(Debug, Clone, Default)]
pub struct Engine {
    pub mode: Mode,
    pub allow: Vec<Rule>,
    pub deny: Vec<Rule>,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Decision {
    Allow,
    Deny,
    Ask,
    Plan,
}

impl Engine {
    pub fn add_allow(&mut self, raw: &str) -> Result<()> {
        self.allow.push(Rule::parse(raw)?);
        Ok(())
    }

    pub fn add_deny(&mut self, raw: &str) -> Result<()> {
        self.deny.push(Rule::parse(raw)?);
        Ok(())
    }

    pub fn evaluate(&self, tool: &str, args: &serde_json::Value, is_write: bool) -> Decision {
        for r in &self.deny {
            if r.matches(tool, args) {
                return Decision::Deny;
            }
        }
        if matches!(self.mode, Mode::Plan) {
            if is_write || is_side_effect_tool(tool) {
                return Decision::Plan;
            }
            return Decision::Allow;
        }
        if self.allow.iter().any(|r| r.matches(tool, args)) {
            return Decision::Allow;
        }
        match self.mode {
            Mode::Plan => Decision::Plan,
            Mode::BypassPermissions | Mode::DontAsk => Decision::Allow,
            Mode::Auto => Decision::Allow,
            Mode::AcceptEdits => {
                if is_write {
                    Decision::Allow
                } else {
                    Decision::Ask
                }
            }
            Mode::Default => Decision::Ask,
        }
    }
}

fn is_side_effect_tool(tool: &str) -> bool {
    matches!(
        tool,
        "run_terminal_cmd" | "bash" | "write_file" | "edit_file" | "multi_edit"
    )
}

fn glob_match(pattern: &str, s: &str) -> bool {
    let mut pi = pattern.chars().peekable();
    let mut si = s.chars().peekable();
    loop {
        match pi.peek().copied() {
            None => return si.peek().is_none(),
            Some('*') => {
                pi.next();
                if pi.peek().is_none() {
                    return true;
                }
                while si.peek().is_some() {
                    if glob_match(
                        &pi.clone().collect::<String>(),
                        &si.clone().collect::<String>(),
                    ) {
                        return true;
                    }
                    si.next();
                }
                return false;
            }
            Some('?') => {
                if si.next().is_none() {
                    return false;
                }
                pi.next();
            }
            Some(c) => {
                if si.next() != Some(c) {
                    return false;
                }
                pi.next();
            }
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use serde_json::json;

    #[test]
    fn parse_rule_with_pattern() {
        let r = Rule::parse("Bash(git status)").unwrap();
        assert_eq!(r.tool, "Bash");
        assert_eq!(r.arg_pattern.as_deref(), Some("git status"));
    }

    #[test]
    fn parse_rule_bare() {
        let r = Rule::parse("Read").unwrap();
        assert_eq!(r.tool, "Read");
        assert_eq!(r.arg_pattern, None);
    }

    #[test]
    fn rule_matches_glob() {
        let r = Rule::parse("Bash(git *)").unwrap();
        assert!(r.matches("Bash", &json!("git status")));
        assert!(r.matches("Bash", &json!("git push origin main")));
        assert!(!r.matches("Bash", &json!("rm -rf /")));
    }

    #[test]
    fn deny_overrides_allow() {
        let mut e = Engine::default();
        e.add_allow("Bash(*)").unwrap();
        e.add_deny("Bash(rm *)").unwrap();
        assert_eq!(
            e.evaluate("Bash", &json!("rm -rf foo"), false),
            Decision::Deny
        );
        assert_eq!(e.evaluate("Bash", &json!("ls"), false), Decision::Allow);
    }

    #[test]
    fn mode_drives_unmatched() {
        let mut e = Engine {
            mode: Mode::BypassPermissions,
            ..Default::default()
        };
        assert_eq!(e.evaluate("X", &json!({}), false), Decision::Allow);
        e.mode = Mode::Default;
        assert_eq!(e.evaluate("X", &json!({}), false), Decision::Ask);
    }

    #[test]
    fn plan_mode_blocks_writes() {
        let e = Engine {
            mode: Mode::Plan,
            ..Default::default()
        };
        assert_eq!(e.evaluate("read_file", &json!({}), false), Decision::Allow);
        assert_eq!(e.evaluate("write_file", &json!({}), true), Decision::Plan);
        assert_eq!(e.evaluate("bash", &json!("ls"), false), Decision::Plan);
        assert_eq!(e.evaluate("grep", &json!({}), false), Decision::Allow);
    }
}

use anyhow::{Context, Result};
use serde::{Deserialize, Serialize};
use std::path::{Path, PathBuf};

#[derive(Debug, Clone, Serialize, Deserialize, Default)]
pub struct Frontmatter {
    #[serde(default)]
    pub name: String,
    #[serde(default)]
    pub description: String,
    #[serde(default)]
    pub prompt_mode: Option<String>,
    #[serde(default)]
    pub model: Option<String>,
    #[serde(default)]
    pub permission_mode: Option<String>,
    #[serde(default)]
    pub capability_mode: Option<String>,
    #[serde(default)]
    pub agents_md: Option<bool>,
    #[serde(default)]
    pub default_fork_context: Option<bool>,
    #[serde(default)]
    pub reasoning_effort: Option<String>,
}

#[derive(Debug, Clone)]
pub struct Agent {
    pub frontmatter: Frontmatter,
    pub system_prompt: String,
    pub path: PathBuf,
    pub source: Source,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Source {
    Builtin,
    User,
    Project,
}

pub fn load_by_name(name: &str, bundled_dir: Option<&Path>) -> Result<Agent> {
    if let Ok(cwd) = std::env::current_dir() {
        let p = cwd
            .join(".openbuild")
            .join("agents")
            .join(format!("{name}.md"));
        if p.exists() {
            return load(&p, Source::Project);
        }
    }
    if let Some(home) = dirs::home_dir() {
        let p = home
            .join(".openbuild")
            .join("agents")
            .join(format!("{name}.md"));
        if p.exists() {
            return load(&p, Source::User);
        }
    }
    if let Some(dir) = bundled_dir {
        let p = dir.join(format!("{name}.md"));
        if p.exists() {
            return load(&p, Source::Builtin);
        }
    }
    anyhow::bail!("agent not found: {name}")
}

pub fn load(path: &Path, source: Source) -> Result<Agent> {
    let text =
        std::fs::read_to_string(path).with_context(|| format!("read agent {}", path.display()))?;
    let (front, body) = split_frontmatter(&text);
    let frontmatter: Frontmatter = if front.is_empty() {
        Frontmatter::default()
    } else {
        serde_yaml::from_str(front).unwrap_or_default()
    };
    let mut fm = frontmatter;
    if fm.name.is_empty() {
        fm.name = path
            .file_stem()
            .and_then(|s| s.to_str())
            .unwrap_or("unnamed")
            .to_string();
    }
    Ok(Agent {
        frontmatter: fm,
        system_prompt: body.trim().to_string(),
        path: path.to_path_buf(),
        source,
    })
}

pub fn discover_all(bundled_dir: Option<&Path>) -> Vec<Agent> {
    let mut out = Vec::new();
    if let Some(dir) = bundled_dir {
        out.extend(scan(dir, Source::Builtin));
    }
    if let Some(home) = dirs::home_dir() {
        out.extend(scan(&home.join(".openbuild").join("agents"), Source::User));
    }
    if let Ok(cwd) = std::env::current_dir() {
        out.extend(scan(
            &cwd.join(".openbuild").join("agents"),
            Source::Project,
        ));
    }
    out
}

fn scan(dir: &Path, source: Source) -> Vec<Agent> {
    let Ok(entries) = std::fs::read_dir(dir) else {
        return Vec::new();
    };
    let mut out = Vec::new();
    for e in entries.flatten() {
        let p = e.path();
        if p.extension().and_then(|s| s.to_str()) != Some("md") {
            continue;
        }
        if let Ok(a) = load(&p, source) {
            out.push(a);
        }
    }
    out
}

fn split_frontmatter(text: &str) -> (&str, &str) {
    if let Some(rest) = text.strip_prefix("---\n") {
        if let Some(end) = rest.find("\n---") {
            let body_start = end + 4;
            let body = if rest.as_bytes().get(body_start) == Some(&b'\n') {
                &rest[body_start + 1..]
            } else {
                &rest[body_start..]
            };
            return (&rest[..end], body);
        }
    }
    ("", text)
}

pub fn render_prompt(prompt: &str, tool_names: &[String]) -> String {
    let mut out = prompt.to_string();
    let by_kind_keys = [
        "read", "list", "search", "execute", "write", "edit", "spawn", "web",
    ];
    for key in by_kind_keys {
        let needle = format!("${{{{ tools.by_kind.{key} }}}}");
        let candidates = match key {
            "read" => vec!["read_file"],
            "list" => vec!["list_dir", "glob"],
            "search" => vec!["grep", "glob"],
            "execute" => vec!["run_terminal_cmd"],
            "write" => vec!["write_file"],
            "edit" => vec!["edit_file"],
            "spawn" => vec!["task"],
            "web" => vec!["web_search", "web_fetch"],
            _ => vec![],
        };
        let names: Vec<&str> = candidates
            .into_iter()
            .filter(|c| tool_names.iter().any(|t| t == c))
            .collect();
        let replacement = if names.is_empty() {
            "(none)".to_string()
        } else {
            names.join(", ")
        };
        out = out.replace(&needle, &replacement);
    }
    out
}

use anyhow::{anyhow, Context, Result};
use serde::{Deserialize, Serialize};
use std::collections::BTreeMap;
use std::process::Stdio;
use std::sync::atomic::{AtomicU64, Ordering};
use std::sync::Arc;
use tokio::io::{AsyncBufReadExt, AsyncWriteExt, BufReader};
use tokio::process::{Child, ChildStdin, ChildStdout};
use tokio::sync::{oneshot, Mutex};

pub const PROTOCOL_VERSION: &str = "2025-06-18";

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct McpTool {
    pub name: String,
    #[serde(default)]
    pub description: String,
    #[serde(default = "empty_schema")]
    pub input_schema: serde_json::Value,
}

fn empty_schema() -> serde_json::Value {
    serde_json::json!({"type": "object", "properties": {}})
}

#[derive(Debug, Serialize)]
struct Request<'a> {
    jsonrpc: &'static str,
    id: u64,
    method: &'a str,
    #[serde(skip_serializing_if = "Option::is_none")]
    params: Option<serde_json::Value>,
}

#[derive(Debug, Serialize)]
struct Notification<'a> {
    jsonrpc: &'static str,
    method: &'a str,
    #[serde(skip_serializing_if = "Option::is_none")]
    params: Option<serde_json::Value>,
}

#[derive(Debug, Deserialize)]
struct Response {
    #[serde(default)]
    id: Option<u64>,
    #[serde(default)]
    result: Option<serde_json::Value>,
    #[serde(default)]
    error: Option<RpcError>,
}

#[derive(Debug, Deserialize)]
struct RpcError {
    code: i64,
    message: String,
}

pub struct StdioClient {
    next_id: AtomicU64,
    stdin: Arc<Mutex<ChildStdin>>,
    pending: Arc<Mutex<BTreeMap<u64, oneshot::Sender<Result<serde_json::Value>>>>>,
    _child: Child,
}

impl StdioClient {
    pub async fn spawn(
        command: &str,
        args: &[String],
        env: &BTreeMap<String, String>,
    ) -> Result<Arc<Self>> {
        let mut child = tokio::process::Command::new(command)
            .args(args)
            .envs(env.iter())
            .stdin(Stdio::piped())
            .stdout(Stdio::piped())
            .stderr(Stdio::inherit())
            .kill_on_drop(true)
            .spawn()
            .with_context(|| format!("spawn mcp server: {command}"))?;
        let stdin = child.stdin.take().context("mcp stdin missing")?;
        let stdout = child.stdout.take().context("mcp stdout missing")?;

        let pending: Arc<Mutex<BTreeMap<u64, oneshot::Sender<Result<serde_json::Value>>>>> =
            Arc::new(Mutex::new(BTreeMap::new()));
        let client = Arc::new(Self {
            next_id: AtomicU64::new(1),
            stdin: Arc::new(Mutex::new(stdin)),
            pending: pending.clone(),
            _child: child,
        });

        tokio::spawn(reader_loop(stdout, pending));
        client.initialize().await?;
        Ok(client)
    }

    async fn initialize(&self) -> Result<()> {
        let params = serde_json::json!({
            "protocolVersion": PROTOCOL_VERSION,
            "capabilities": {"tools": {}},
            "clientInfo": {"name": "openbuild", "version": env!("CARGO_PKG_VERSION")},
        });
        let _ = self.call("initialize", Some(params)).await?;
        self.notify("notifications/initialized", None).await?;
        Ok(())
    }

    pub async fn list_tools(&self) -> Result<Vec<McpTool>> {
        let v = self.call("tools/list", None).await?;
        let tools = v
            .get("tools")
            .ok_or_else(|| anyhow!("tools/list missing tools"))?
            .clone();
        Ok(serde_json::from_value(tools)?)
    }

    pub async fn call_tool(&self, name: &str, args: serde_json::Value) -> Result<String> {
        let params = serde_json::json!({"name": name, "arguments": args});
        let v = self.call("tools/call", Some(params)).await?;
        if let Some(content) = v.get("content").and_then(|c| c.as_array()) {
            let mut out = String::new();
            for item in content {
                if let Some(t) = item.get("text").and_then(|t| t.as_str()) {
                    out.push_str(t);
                }
            }
            return Ok(out);
        }
        Ok(v.to_string())
    }

    async fn call(
        &self,
        method: &str,
        params: Option<serde_json::Value>,
    ) -> Result<serde_json::Value> {
        let id = self.next_id.fetch_add(1, Ordering::Relaxed);
        let (tx, rx) = oneshot::channel();
        self.pending.lock().await.insert(id, tx);
        let req = Request {
            jsonrpc: "2.0",
            id,
            method,
            params,
        };
        let line = serde_json::to_string(&req)? + "\n";
        self.stdin.lock().await.write_all(line.as_bytes()).await?;
        self.stdin.lock().await.flush().await?;
        rx.await.context("mcp response channel closed")?
    }

    async fn notify(&self, method: &str, params: Option<serde_json::Value>) -> Result<()> {
        let n = Notification {
            jsonrpc: "2.0",
            method,
            params,
        };
        let line = serde_json::to_string(&n)? + "\n";
        self.stdin.lock().await.write_all(line.as_bytes()).await?;
        self.stdin.lock().await.flush().await?;
        Ok(())
    }
}

pub struct HttpClient {
    url: String,
    http: reqwest::Client,
    next_id: AtomicU64,
}

impl HttpClient {
    pub async fn connect(url: &str) -> Result<Arc<Self>> {
        let client = Arc::new(Self {
            url: url.to_string(),
            http: reqwest::Client::builder()
                .user_agent("openbuild/0.0.1")
                .build()?,
            next_id: AtomicU64::new(1),
        });
        client.initialize().await?;
        Ok(client)
    }

    async fn initialize(&self) -> Result<()> {
        let params = serde_json::json!({
            "protocolVersion": PROTOCOL_VERSION,
            "capabilities": {"tools": {}},
            "clientInfo": {"name": "openbuild", "version": env!("CARGO_PKG_VERSION")},
        });
        let _ = self.call("initialize", Some(params)).await?;
        Ok(())
    }

    pub async fn list_tools(&self) -> Result<Vec<McpTool>> {
        let v = self.call("tools/list", None).await?;
        let tools = v
            .get("tools")
            .ok_or_else(|| anyhow!("tools/list missing tools"))?
            .clone();
        Ok(serde_json::from_value(tools)?)
    }

    pub async fn call_tool(&self, name: &str, args: serde_json::Value) -> Result<String> {
        let params = serde_json::json!({"name": name, "arguments": args});
        let v = self.call("tools/call", Some(params)).await?;
        if let Some(content) = v.get("content").and_then(|c| c.as_array()) {
            let mut out = String::new();
            for item in content {
                if let Some(t) = item.get("text").and_then(|t| t.as_str()) {
                    out.push_str(t);
                }
            }
            return Ok(out);
        }
        Ok(v.to_string())
    }

    async fn call(
        &self,
        method: &str,
        params: Option<serde_json::Value>,
    ) -> Result<serde_json::Value> {
        let id = self.next_id.fetch_add(1, Ordering::Relaxed);
        let req = Request {
            jsonrpc: "2.0",
            id,
            method,
            params,
        };
        let resp = self
            .http
            .post(&self.url)
            .header("content-type", "application/json")
            .header("accept", "application/json, text/event-stream")
            .json(&req)
            .send()
            .await?;
        let ct = resp
            .headers()
            .get("content-type")
            .and_then(|v| v.to_str().ok())
            .unwrap_or("")
            .to_string();
        let body = resp.text().await?;
        let parsed: Response = if ct.contains("text/event-stream") {
            let mut data = String::new();
            for line in body.lines() {
                if let Some(rest) = line.strip_prefix("data:") {
                    let rest = rest.strip_prefix(' ').unwrap_or(rest);
                    data.push_str(rest);
                }
            }
            serde_json::from_str(&data)?
        } else {
            serde_json::from_str(&body)?
        };
        match (parsed.result, parsed.error) {
            (_, Some(e)) => Err(anyhow!("mcp http error {}: {}", e.code, e.message)),
            (Some(v), None) => Ok(v),
            (None, None) => Err(anyhow!("mcp http response missing result and error")),
        }
    }
}

async fn reader_loop(
    stdout: ChildStdout,
    pending: Arc<Mutex<BTreeMap<u64, oneshot::Sender<Result<serde_json::Value>>>>>,
) {
    let mut reader = BufReader::new(stdout).lines();
    while let Ok(Some(line)) = reader.next_line().await {
        let resp: Response = match serde_json::from_str(&line) {
            Ok(r) => r,
            Err(_) => continue,
        };
        let Some(id) = resp.id else { continue };
        let tx = pending.lock().await.remove(&id);
        if let Some(tx) = tx {
            let outcome = match (resp.result, resp.error) {
                (_, Some(e)) => Err(anyhow!("mcp error {}: {}", e.code, e.message)),
                (Some(v), None) => Ok(v),
                (None, None) => Err(anyhow!("mcp response missing result and error")),
            };
            let _ = tx.send(outcome);
        }
    }
}

use crate::Tool;
use async_trait::async_trait;
use openbuild_core::tool::ToolSchema;
use serde::Deserialize;

pub struct WebSearch {
    pub disabled: bool,
}

#[derive(Deserialize)]
struct Input {
    query: String,
    #[serde(default = "default_limit")]
    limit: usize,
}

fn default_limit() -> usize {
    10
}

#[async_trait]
impl Tool for WebSearch {
    fn schema(&self) -> ToolSchema {
        ToolSchema {
            name: "web_search".into(),
            description:
                "Search the web (DuckDuckGo HTML). Returns title + URL + snippet for top results."
                    .into(),
            input_schema: serde_json::json!({
                "type": "object",
                "properties": {
                    "query": {"type": "string"},
                    "limit": {"type": "integer", "minimum": 1, "maximum": 25}
                },
                "required": ["query"]
            }),
        }
    }

    async fn run(&self, input: serde_json::Value) -> Result<String, String> {
        if self.disabled {
            return Err("web_search disabled by --disable-web-search".into());
        }
        let i: Input = serde_json::from_value(input).map_err(|e| e.to_string())?;
        let url = format!(
            "https://html.duckduckgo.com/html/?q={}",
            urlencoding::encode(&i.query)
        );
        let client = reqwest::Client::builder()
            .user_agent("openbuild/0.0.1")
            .build()
            .map_err(|e| e.to_string())?;
        let html = client
            .get(&url)
            .send()
            .await
            .map_err(|e| e.to_string())?
            .text()
            .await
            .map_err(|e| e.to_string())?;
        let results = parse_ddg(&html, i.limit);
        let mut out = String::new();
        for r in results {
            out.push_str(&format!("{}\n{}\n{}\n\n", r.title, r.url, r.snippet));
        }
        if out.is_empty() {
            return Err("no results parsed; DuckDuckGo HTML format may have changed".into());
        }
        Ok(out)
    }
}

struct Hit {
    title: String,
    url: String,
    snippet: String,
}

fn parse_ddg(html: &str, limit: usize) -> Vec<Hit> {
    let mut out = Vec::new();
    let mut cursor = html;
    while out.len() < limit {
        let Some(title_start) = cursor.find("class=\"result__a\"") else {
            break;
        };
        cursor = &cursor[title_start..];
        let Some(href_start) = cursor.find("href=\"") else {
            break;
        };
        let after_href = &cursor[href_start + 6..];
        let Some(href_end) = after_href.find('"') else {
            break;
        };
        let url = decode_ddg_redirect(&after_href[..href_end]);
        let Some(title_open) = after_href.find('>') else {
            break;
        };
        let after_title = &after_href[title_open + 1..];
        let Some(title_close) = after_title.find("</a>") else {
            break;
        };
        let title = strip_tags(&after_title[..title_close]);
        let mut snippet = String::new();
        if let Some(snip_start) = after_title.find("class=\"result__snippet\"") {
            let after_snip = &after_title[snip_start..];
            if let Some(open) = after_snip.find('>') {
                if let Some(close) = after_snip[open + 1..].find("</a>") {
                    snippet = strip_tags(&after_snip[open + 1..open + 1 + close]);
                }
            }
        }
        out.push(Hit {
            title: title.trim().to_string(),
            url,
            snippet: snippet.trim().to_string(),
        });
        cursor = &after_title[title_close..];
    }
    out
}

fn decode_ddg_redirect(href: &str) -> String {
    let cleaned = href.trim_start_matches("//");
    if let Some(idx) = cleaned.find("uddg=") {
        let rest = &cleaned[idx + 5..];
        let raw = rest.split('&').next().unwrap_or(rest);
        return urlencoding::decode(raw)
            .map(|s| s.into_owned())
            .unwrap_or_else(|_| raw.to_string());
    }
    if cleaned.starts_with("http") {
        cleaned.to_string()
    } else {
        format!("https://{cleaned}")
    }
}

fn strip_tags(s: &str) -> String {
    let mut out = String::new();
    let mut in_tag = false;
    for c in s.chars() {
        match c {
            '<' => in_tag = true,
            '>' => in_tag = false,
            _ if !in_tag => out.push(c),
            _ => {}
        }
    }
    out
}
